package main

import (
 "bytes"
 "encoding/json"
 "net/http"
 "strings"
 "time"
)

var fraudClient=&http.Client{Timeout:3*time.Second,CheckRedirect:func(*http.Request,[]*http.Request)error{return http.ErrUseLastResponse}}
func (a *App) fraud(w http.ResponseWriter,r *http.Request,parts []string){org:=currentOrgID(r,a.orgID)
 if len(parts)==2&&parts[1]=="analyze"&&r.Method==http.MethodPost{var in struct{Amount int64 `json:"amount"`;Currency string `json:"currency"`;Reference string `json:"transaction_reference"`};if decode(r,&in)!=nil||in.Amount<=0||len(in.Currency)!=3||strings.TrimSpace(in.Reference)==""{bad(w,r,"positive amount, three-letter currency, and transaction_reference are required");return};body,_:=json.Marshal(in);url:=strings.TrimRight(env("FRAUD_SERVICE_URL","http://fraud:8090"),"/")+"/v1/analyze";req,err:=http.NewRequestWithContext(r.Context(),http.MethodPost,url,bytes.NewReader(body));if err!=nil{writeJSON(w,500,problem{Error:"risk request failed"});return};req.Header.Set("Content-Type","application/json");resp,err:=fraudClient.Do(req);if err!=nil{writeJSON(w,503,problem{Error:"fraud service unavailable",RequestID:requestID(r)});return};defer resp.Body.Close();if resp.StatusCode<200||resp.StatusCode>=300{writeJSON(w,502,problem{Error:"fraud service returned an error",RequestID:requestID(r)});return};var result struct{Reference string `json:"transaction_reference"`;Score int `json:"risk_score"`;Level string `json:"risk_level"`;Decision string `json:"decision"`;Model string `json:"model_version"`;Mode string `json:"mode"`};if json.NewDecoder(http.MaxBytesReader(w,resp.Body,1<<20)).Decode(&result)!=nil{writeJSON(w,502,problem{Error:"invalid fraud service response"});return};if result.Score<0||result.Score>100||result.Model==""||(result.Decision!="allow"&&result.Decision!="review"&&result.Decision!="block"){writeJSON(w,502,problem{Error:"fraud service returned an invalid assessment",RequestID:requestID(r)});return};assessmentID:="ras_"+newID();tx,err:=a.db.BeginTx(r.Context(),nil);if err!=nil{writeJSON(w,500,problem{Error:"database error"});return};defer tx.Rollback();_,err=tx.ExecContext(r.Context(),`INSERT INTO risk_assessments(id,organization_id,transaction_reference,risk_score,risk_level,decision,model_version) VALUES($1,$2,$3,$4,$5,$6,$7)`,assessmentID,org,in.Reference,result.Score,result.Level,result.Decision,result.Model);if err!=nil{writeJSON(w,500,problem{Error:"risk assessment could not be recorded"});return};var caseID any;if result.Decision=="review"||result.Decision=="block"{id:="case_"+newID();if _,err=tx.ExecContext(r.Context(),`INSERT INTO fraud_cases(id,organization_id,assessment_id,priority) VALUES($1,$2,$3,$4)`,id,org,assessmentID,result.Level);err!=nil{writeJSON(w,500,problem{Error:"fraud review case could not be created"});return};caseID=id;if _,err=tx.ExecContext(r.Context(),`INSERT INTO outbox_events(id,organization_id,aggregate_type,aggregate_id,event_type,payload) VALUES($1,$2,'fraud_case',$3,'fraud.case.opened',jsonb_build_object('case_id',$3::text,'assessment_id',$4::text,'priority',$5::text))`,"evt_"+newID(),org,id,assessmentID,result.Level);err!=nil{writeJSON(w,500,problem{Error:"fraud case event could not be recorded"});return}};if err=tx.Commit();err!=nil{writeJSON(w,409,problem{Error:"risk assessment conflict"});return};writeJSON(w,200,map[string]any{"id":assessmentID,"transaction_reference":in.Reference,"risk_score":result.Score,"risk_level":result.Level,"decision":result.Decision,"model_version":result.Model,"mode":"sandbox","case_id":caseID});return}
 if len(parts)==4&&parts[1]=="cases"&&parts[3]=="resolve"&&r.Method==http.MethodPost{var in struct{Note string `json:"note"`;Outcome string `json:"outcome"`};if decode(r,&in)!=nil||strings.TrimSpace(in.Note)==""||(in.Outcome!="confirmed"&&in.Outcome!="false_positive"){bad(w,r,"note and outcome (confirmed or false_positive) are required");return};tx,err:=a.db.BeginTx(r.Context(),nil);if err!=nil{writeJSON(w,500,problem{Error:"database error"});return};defer tx.Rollback();res,err:=tx.ExecContext(r.Context(),`UPDATE fraud_cases SET status='resolved',resolved_at=now() WHERE id=$1 AND organization_id=$2 AND status<>'resolved'`,parts[2],org);if err!=nil{writeJSON(w,500,problem{Error:"case update failed"});return};n,_:=res.RowsAffected();if n==0{notFound(w,r);return};p:=principalFrom(r);if _,err=tx.ExecContext(r.Context(),`INSERT INTO fraud_case_notes(id,organization_id,case_id,author_id,note) VALUES($1,$2,$3,$4,$5)`,"note_"+newID(),org,parts[2],nullable(p.userID),in.Note);err!=nil{writeJSON(w,500,problem{Error:"case note could not be saved"});return};if _,err=tx.ExecContext(r.Context(),`INSERT INTO audit_logs(id,organization_id,actor_id,action,resource_type,resource_id,metadata) VALUES($1,$2,$3,'fraud.case.resolved','fraud_case',$4,jsonb_build_object('outcome',$5::text))`,"aud_"+newID(),org,nullable(p.userID),parts[2],in.Outcome);err!=nil{writeJSON(w,500,problem{Error:"audit record could not be saved"});return};if _,err=tx.ExecContext(r.Context(),`INSERT INTO outbox_events(id,organization_id,aggregate_type,aggregate_id,event_type,payload) VALUES($1,$2,'fraud_case',$3,'fraud.case.resolved',jsonb_build_object('case_id',$3::text,'outcome',$4::text))`,"evt_"+newID(),org,parts[2],in.Outcome);err!=nil{writeJSON(w,500,problem{Error:"event could not be saved"});return};if err=tx.Commit();err!=nil{writeJSON(w,409,problem{Error:"case review conflict"});return};writeJSON(w,200,map[string]any{"id":parts[2],"status":"resolved","outcome":in.Outcome});return}
 if len(parts)==2&&parts[1]=="cases"&&r.Method==http.MethodGet{rows,err:=a.db.QueryContext(r.Context(),`SELECT c.id,c.status,c.priority,c.created_at,a.transaction_reference,a.risk_score,a.risk_level FROM fraud_cases c JOIN risk_assessments a ON a.id=c.assessment_id AND a.organization_id=c.organization_id WHERE c.organization_id=$1 ORDER BY c.created_at DESC LIMIT 100`,org);if err!=nil{writeJSON(w,500,problem{Error:"database error"});return};defer rows.Close();data:=[]map[string]any{};for rows.Next(){var id,status,priority,reference,level string;var score int;var created time.Time;if rows.Scan(&id,&status,&priority,&created,&reference,&score,&level)==nil{data=append(data,map[string]any{"id":id,"status":status,"priority":priority,"created_at":created,"transaction_reference":reference,"risk_score":score,"risk_level":level})}};writeJSON(w,200,map[string]any{"data":data});return}
 notFound(w,r)
}
